d={1:0,3:1,5:2,7:3,9:4}
cells=[(r,c,g[r,c]) for r in range(H) for c in range(W) if g[r,c] in d]
print(len(cells))
# solve d = (a*r + b*c + k) mod 5
import itertools
ok=[]
for a in range(5):
    for b in range(5):
        k=(d[cells[0][2]]-a*cells[0][0]-b*cells[0][1])%5
        if all((a*r+b*c+k)%5==d[v] for r,c,v in cells): ok.append((a,b,k))
print(ok)

# test v = (R[r]+C[c]) mod 5 in digit encoding
import numpy as np
enc={1:0,3:1,5:2,7:3,9:4}
E=np.full((H,W),-1)
for r,c,v in cells: E[r,c]=enc[v]
# rows/cols with enough known cells: use rows 2..27 cols 2..27
# check row r known values consistent with fixed row offset? Two cells same row differ by column diff only if same row: E[r,c2]-E[r,c1] should equal C[c2]-C[c1] independent of r.
pairs=set()
for r in range(2,H):
    known=[c for c in range(2,W) if E[r,c]>=0]
    for i in range(len(known)):
        for j in range(i+1,len(known)):
            pairs.add(((known[i],known[j]),(E[r,known[j]]-E[r,known[i]])%5))
# build constraint: for col pair (c1,c2) the diff must be consistent
diffs=defaultdict(set)
for (c1,c2),d in pairs: diffs[(c1,c2)].add(d)
bad={k:v for k,v in diffs.items() if len(v)>1}
print(len(diffs), len(bad), list(bad.items())[:10])

from collections import Counter
out=g.copy()
# tile from encoded values, rows/cols 3..27
T={}
for i in range(5):
    for j in range(5):
        cnt=Counter(E[r,c] for r in range(3,H) for c in range(3,W) if r%5==i and c%5==j and E[r,c]>=0)
        T[(i,j)]=cnt.most_common(1)[0][0]
dec={v:k for k,v in enc.items()}
zeros=[(r,c) for r in range(H) for c in range(W) if g[r,c]==0]
for r,c in zeros:
    if r>=3 and c>=3:
        out[r,c]=dec[T[(r%5,c%5)]]
    elif r<=1 or c<=1:
        out[r,c]=1
    else: # r==2 or c==2
        out[r,c]=4
print('remaining zeros', (out==0).sum())
# verify tile consistency of filled cells with neighbors
print(out[3,11:18], out[15,9:16], out[12,0:6])
print([list(map(int,row)) for row in out][:6])
